 'AGT':'S','AGC':'S','AGA':'R','AGG':'R','GGT':'G','GGC':'G','GGA':'G','GGG':'G'}
def tr(s): return "".join(code.get(s[i:i+3],'?') for i in range(0,len(s)-2,3))

def orfs_any(s):
    # find ORFs between stops, report longest, with the first ATG if present
    res=[]
    for f in range(3):
        start=f; i=f
        while i+3<=len(s):
            if s[i:i+3] in stops:
                seg=s[start:i]
                # find first ATG in seg
                k=seg.find('ATG')
                if k!=-1:
                    res.append((start+k,i))
                start=i+3
            i+=3
        seg=s[start:]
        k=seg.find('ATG')
        if k!=-1: res.append((start+k,len(s)))
    return res

plus=[(a,b,'+') for a,b in orfs_any(seq)]
minus=[(len(seq)-b,len(seq)-a,'-') for a,b in orfs_any(rc)]
allorf=sorted(plus+minus,key=lambda x:-(x[1]-x[0]))
for a,b,st in allorf[:12]:
    if st=='+':
        prot=tr(seq[a:b])
    else:
        prot=tr(seq[a:b].translate(comp)[::-1])
    print(st,a,b,(b-a), "aa",(b-a)//3, prot[:70])
